// ETAPE 1 - Schema JSON, coherence topic/identite, conversion d'unite, numero de sequence.
// Entree : msg.topic = ctmc/patients/<pid>/glycemie ; msg.payload = texte JSON.
// Sorties : [1] message valide, [2] rejet (journal d'audit).
const topicPid = String(msg.topic).split('/')[2];
const reject = (reason, extra) => {
    msg.audit = Object.assign({ event: 'rejected', stage: 'schema', reason: reason, pid: topicPid }, extra || {});
    return [null, msg];
};
let p;
try { p = JSON.parse(msg.payload); } catch (e) { return reject('not_json'); }
if (!p || typeof p !== 'object' || Array.isArray(p)) return reject('not_json');
for (const k of ['device_id', 'patient_pseudo_id', 'timestamp', 'observations', 'consent', 'seq']) {
    if (!(k in p)) return reject('missing_field', { field: k });
}
// Un appareil ne peut publier que sous son propre identifiant (anti-usurpation)
if (p.patient_pseudo_id !== topicPid) {
    return reject('pid_topic_mismatch', { claimed: String(p.patient_pseudo_id).slice(0, 40) });
}
// La passerelle est vivante (utilise par le chien de garde)
const seen = flow.get('lastSeen') || {};
seen[topicPid] = Date.now();
flow.set('lastSeen', seen);

const t = Date.parse(p.timestamp);
if (isNaN(t)) return reject('bad_timestamp');
if (!Array.isArray(p.observations)) return reject('bad_observations');
// Code MDC 32 bits de MDC_CONC_GLU_CAPILLARY_WHOLEBLOOD (IEEE 11073-10101)
const o = p.observations.find(x => x && x.mdc_code === 160184);
if (!o) return reject('missing_glucose_observation');
if (typeof o.value !== 'number' || !isFinite(o.value)) return reject('non_numeric_value');
let value = o.value, converted = false;
if (o.unit_ucum === 'mmol/L') { value = Math.round(o.value * 18.016); converted = true; }
else if (o.unit_ucum !== 'mg/dL') return reject('unit_mismatch', { unit: String(o.unit_ucum).slice(0, 20) });

// Detection de pertes : trous dans la sequence
const last = context.get('lastSeq') || {};
let gap = 0;
if (typeof p.seq === 'number' && last[topicPid] !== undefined && p.seq > last[topicPid] + 1) {
    gap = p.seq - last[topicPid] - 1;
}
last[topicPid] = p.seq;
context.set('lastSeq', last);

msg.obs = {
    pid: topicPid, device_id: String(p.device_id).slice(0, 30), profile: p.profile || 'inconnu',
    consent: p.consent, ts: p.timestamp, ts_ms: t, seq: p.seq,
    value_mgdl: value, converted: converted, quality: o.quality || 'valid', gap: gap
};
return [msg, null];

// ETAPE 2 - Consentement (loi 09-08) : sans consentement explicite, RIEN n'est traite ni stocke.
// Le journal ne contient ni valeur ni mesure : seulement le pseudonyme et le motif.
if (msg.obs.consent !== true) {
    msg.audit = { event: 'rejected', stage: 'consent', reason: 'no_consent', pid: msg.obs.pid };
    return [null, msg];
}
return [msg, null];

// ETAPE 3 - Plausibilite physiologique de la glycemie (mg/dL) et qualite declaree par le capteur.
const MIN = 20, MAX = 600;
const o = msg.obs;
const reject = (reason) => {
    msg.audit = { event: 'rejected', stage: 'plausibility', reason: reason, pid: o.pid,
                  seq: o.seq, value_mgdl: o.value_mgdl };
    return [null, msg];
};
if (o.quality !== 'valid') return reject('quality_' + o.quality);
if (o.value_mgdl < MIN || o.value_mgdl > MAX) return reject('implausible_value');
return [msg, null];

// ETAPE 4 - Moteur d'alertes CTSMC (seuils en g/L = mg/dL / 100), dedoublonnage par patient.
// Sorties : [1] alerte (ou fin d'alerte) a publier, [2] mesure acceptee.
const RENOTIFY_MS = (Number(env.get('RENOTIFY_S')) || 60) * 1000;

// Regles par profil : modifiables ici. Seuils du tableau A01-A06 de la fiche CTSMC.
const RULES = {
    T1: { hypo: 0.70, recipients_hypo: 'Infirmier de garde + medecin specialiste' },
    T2: { hypo: 0.70, recipients_hypo: 'Infirmier de garde + medecin' }
};
const rule = RULES[msg.obs.profile] || RULES.T2;

function classify(g) {
    if (g < rule.hypo) return { id: 'A01', level: 'rouge', label: 'Hypoglycemie',
        recipients: rule.recipients_hypo, action: 'Alerte immediate : afficher la valeur mesuree' };
    if (g <= 1.10) return { id: 'A02', level: null, label: 'Normal' };
    if (g < 2.00)  return { id: 'A03', level: null, label: 'A surveiller' };
    if (g < 2.50)  return { id: 'A04', level: 'orange', label: 'Hyperglycemie elevee',
        recipients: 'Infirmier', action: 'Notifier le personnel soignant pour evaluation' };
    if (g <= 5.00) return { id: 'A05', level: 'rouge', label: 'Hyperglycemie urgente',
        recipients: 'Infirmier + medecin', action: 'Evaluation clinique, cetones selon protocole medical' };
    return { id: 'A06', level: 'rouge', label: 'Hyperglycemie critique',
        recipients: 'Infirmier + medecin', action: 'Evaluation medicale rapide et prioritaire' };
}

const o = msg.obs;
const g = o.value_mgdl / 100;
const cls = classify(g);
const now = Date.now();
const CLEAR_N = Number(env.get('CLEAR_N')) || 2;           // lectures normales consecutives pour lever l'alerte
const SEV = { A04: 1, A05: 2, A06: 3, A01: 3 };            // gravite : seule une aggravation re-notifie
const state = context.get('state') || {};
const prev = state[o.pid];
let alertMsg = null;

const base = {
    patient_pseudo_id: o.pid, profile: o.profile, device_id: o.device_id, seq: o.seq,
    value_mgdl: o.value_mgdl, value_g_per_l: Math.round(g * 100) / 100,
    ts_measure: o.ts, ts_detect: new Date(now).toISOString(), latency_ms: now - o.ts_ms
};
const emit = (kind, extra) => {
    const payload = Object.assign({ kind: kind }, extra, base);
    return { topic: kind === 'resolved' ? 'ctmc/alertes/resolu' : 'ctmc/alertes/' + payload.level, qos: 1,
             payload: payload, audit: Object.assign({ event: 'alert' }, payload) };
};

if (cls.level) {
    const info = { alert_id: cls.id, level: cls.level, label: cls.label, recipients: cls.recipients, action: cls.action };
    if (!prev) {
        alertMsg = emit('new', info);
        state[o.pid] = { id: cls.id, since: now, lastNotify: now, clear: 0 };
    } else if (prev.id !== cls.id && SEV[cls.id] > SEV[prev.id]) {
        alertMsg = emit('escalation', Object.assign({ previous_alert_id: prev.id }, info));
        state[o.pid] = { id: cls.id, since: prev.since, lastNotify: now, clear: 0 };
    } else if (prev.id !== cls.id) {
        // attenuation (ex. A06 -> A05) : on suit le niveau sans renotifier (evite le va-et-vient autour d'un seuil)
        state[o.pid] = { id: cls.id, since: prev.since, lastNotify: prev.lastNotify, clear: 0 };
    } else if ((now - prev.lastNotify) >= RENOTIFY_MS) {
        alertMsg = emit('reminder', info);
        prev.lastNotify = now; prev.clear = 0;
    } else {
        prev.clear = 0;
    }
} else if (prev) {
    prev.clear = (prev.clear || 0) + 1;
    if (prev.clear >= CLEAR_N) {
        alertMsg = emit('resolved', { alert_id: prev.id, level: 'resolu', label: 'Retour a la normale',
                                      duration_s: Math.round((now - prev.since) / 1000) });
        delete state[o.pid];
    }
}
context.set('state', state);

msg.audit = { event: 'accepted', pid: o.pid, seq: o.seq, value_mgdl: o.value_mgdl,
              value_g_per_l: base.value_g_per_l, class: cls.id, latency_ms: base.latency_ms,
              gap: o.gap, converted: o.converted };
msg.cls = cls;
msg.payload = Object.assign({ class: cls.id }, base);
return [alertMsg, msg];

// Statut des passerelles (LWT) : ctmc/devices/<GW-pid>/status = online | offline (retained).
const gw = String(msg.topic).split('/')[2] || '';
const pid = gw.startsWith('GW-') ? gw.slice(3) : gw;
const status = String(msg.payload).trim();
const off = flow.get('offline') || {};
const seen = flow.get('lastSeen') || {};
const now = Date.now();
const mk = (kind, level, label) => {
    const payload = { kind: kind, alert_id: 'S01', level: level, label: label, patient_pseudo_id: pid,
        device_id: gw, ts_detect: new Date(now).toISOString(),
        recipients: 'Infirmier de garde', action: 'Verifier la passerelle et les capteurs du patient' };
    return { topic: kind === 'resolved' ? 'ctmc/alertes/resolu' : 'ctmc/alertes/' + level, qos: 1,
             payload: payload, audit: Object.assign({ event: 'alert' }, payload) };
};
if (status === 'offline') {
    if (off[pid]) return null;
    off[pid] = now; flow.set('offline', off);
    return mk('new', 'orange', 'Passerelle hors ligne (LWT)');
}
if (status === 'online') {
    seen[pid] = now; flow.set('lastSeen', seen);
    if (off[pid]) {
        delete off[pid]; flow.set('offline', off);
        return mk('resolved', 'resolu', 'Passerelle de nouveau en ligne');
    }
}
return null;

// Chien de garde : aucune donnee recue depuis N secondes alors que la passerelle se dit en ligne.
const limit = (Number(env.get('SILENCE_THRESHOLD_S')) || 20) * 1000;
const seen = flow.get('lastSeen') || {};
const off = flow.get('offline') || {};
const silent = flow.get('silent') || {};
const now = Date.now();
const out = [];
const mk = (kind, level, label, pid) => {
    const payload = { kind: kind, alert_id: 'S02', level: level, label: label, patient_pseudo_id: pid,
        ts_detect: new Date(now).toISOString(), silence_s: Math.round((now - seen[pid]) / 1000),
        recipients: 'Infirmier de garde', action: 'Verifier la transmission des mesures' };
    return { topic: kind === 'resolved' ? 'ctmc/alertes/resolu' : 'ctmc/alertes/' + level, qos: 1,
             payload: payload, audit: Object.assign({ event: 'alert' }, payload) };
};
for (const pid of Object.keys(seen)) {
    if (off[pid]) continue;
    const age = now - seen[pid];
    if (age > limit && !silent[pid]) {
        silent[pid] = now;
        out.push(mk('new', 'orange', 'Aucune donnee recue', pid));
    } else if (age <= limit && silent[pid]) {
        delete silent[pid];
        out.push(mk('resolved', 'resolu', 'Donnees de nouveau recues', pid));
    }
}
flow.set('silent', silent);
return out.length ? [out] : null;

// Journal d'audit : une ligne JSON par decision (pseudonymes uniquement, aucune identite).
if (!msg.audit) return null;
return { payload: JSON.stringify(Object.assign({ ts: new Date().toISOString() }, msg.audit)) };

// Tableau de bord : met a jour l'etat affiche (contexte de flux) a partir des memes evenements que l'audit.
const a = msg.audit;
if (!a) return null;
const st = flow.get('dash') || { latest: {}, active: {}, log: [], rejects: {}, accepted: 0, rejected: 0, gaps: 0 };
let chart = null, notif = null;
const hhmmss = () => new Date().toLocaleTimeString('fr-FR', { hour12: false });

if (a.event === 'accepted') {
    st.accepted++; st.gaps += (a.gap || 0);
    st.latest[a.pid] = { mg: a.value_mgdl, gl: a.value_g_per_l, cls: a.class, ts: Date.now(),
                         profile: (msg.payload && msg.payload.profile) || '' };
    chart = { topic: a.pid, payload: a.value_mgdl };
} else if (a.event === 'rejected') {
    st.rejected++;
    const k = a.stage + ' / ' + a.reason;
    st.rejects[k] = (st.rejects[k] || 0) + 1;
} else if (a.event === 'alert') {
    const family = String(a.alert_id).startsWith('A') ? 'A' : a.alert_id;
    const key = a.patient_pseudo_id + ':' + family;
    const val = a.value_mgdl !== undefined ? a.value_mgdl + ' mg/dL' : '';
    if (a.kind === 'resolved') {
        delete st.active[key];
    } else {
        st.active[key] = { since: hhmmss(), patient: a.patient_pseudo_id, id: a.alert_id,
                           level: a.level, label: a.label, value: val };
    }
    if (a.kind !== 'reminder') {
        st.log.unshift({ time: hhmmss(), patient: a.patient_pseudo_id, id: a.alert_id, kind: a.kind,
                         label: a.label, value: val });
        st.log = st.log.slice(0, 12);
        const colors = { rouge: '#c62828', orange: '#ef6c00', resolu: '#2e7d32' };
        notif = { payload: a.alert_id + ' - ' + a.label + ' - ' + a.patient_pseudo_id + (val ? ' (' + val + ')' : ''),
                  color: colors[a.level] || '#455a64' };
    }
}
flow.set('dash', st);
return [chart, notif];

// Rendu periodique (toutes les 2 s) des tableaux et compteurs.
const st = flow.get('dash') || { latest: {}, active: {}, log: [], rejects: {}, accepted: 0, rejected: 0, gaps: 0 };
const off = flow.get('offline') || {};
const silent = flow.get('silent') || {};
const seen = flow.get('lastSeen') || {};
const now = Date.now();
const NAMES = { A01: 'A01 Hypoglycemie', A02: 'A02 Normal', A03: 'A03 A surveiller', A04: 'A04 Hyperglycemie elevee',
                A05: 'A05 Hyperglycemie urgente', A06: 'A06 Hyperglycemie critique' };
const ICON = { A01: '🔴', A02: '🟢', A03: '🟡', A04: '🟠', A05: '🔴', A06: '🔴' };

const pids = Array.from(new Set(Object.keys(st.latest).concat(Object.keys(seen)))).sort();
const patients = pids.map(pid => {
    const l = st.latest[pid];
    let gw = '—';
    if (off[pid]) gw = '⛔ HORS LIGNE';
    else if (silent[pid]) gw = '🟠 SILENCE';
    else if (seen[pid]) gw = '🟢 EN LIGNE';
    return { patient: pid, profile: l ? l.profile : '', mg: l ? l.mg : '', gl: l ? l.gl : '',
             level: l ? (ICON[l.cls] || '') + ' ' + (NAMES[l.cls] || l.cls) : '—', gateway: gw,
             age: seen[pid] ? Math.round((now - seen[pid]) / 1000) + ' s' : '' };
});
const active = Object.values(st.active).map(x => Object.assign({}, x, {
    level: (x.level === 'rouge' ? '🔴 ' : '🟠 ') + x.level }));
const rejects = Object.keys(st.rejects).map(k => ({ reason: k, n: st.rejects[k] }));

// Seuils de reference traces sur le graphique (une fois toutes les 3 executions)
const n = (context.get('n') || 0) + 1; context.set('n', n);
let thr = null;
if (st.accepted > 0 && n % 3 === 0) thr = [{ topic: 'Seuil hypoglycemie 70', payload: 70 },
                                           { topic: 'Seuil urgent 250', payload: 250 }];
const M = (x) => ({ payload: x });
return [M(patients), M(active), M(rejects), M(String(st.accepted)), M(String(st.rejected)),
        M(String(st.gaps)), M(st.log), thr];
